export const policyAcknowledgementReport = async (
  code: string,
  params?: PolicyAcknowledgementReportParams,
  options?: RequestInit
): Promise<policyAcknowledgementReportResponseSuccess> => {
  const res = await fetch(getPolicyAcknowledgementReportUrl(code, params), {
    ...options,
    method: 'GET'
  })

  const body = [204, 205, 304].includes(res.status) ? null : await res.text()
  if (!res.ok) {
    const err: globalThis.Error & { info?: policyAcknowledgementReportResponseError['data']; status?: number } =
      new globalThis.Error()
    const data: policyAcknowledgementReportResponseError['data'] = body ? JSON.parse(body) : {}
    err.info = data
    err.status = res.status
    throw err
  }
  const data: policyAcknowledgementReportResponseSuccess['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as policyAcknowledgementReportResponseSuccess
}

export const getPolicyAcknowledgementReportQueryKey = (code: string, params?: PolicyAcknowledgementReportParams) => {
  return [`${env.API_BASE_URL}/api/v1/policies/${code}/acknowledgements`, ...(params ? [params] : [])] as const
}

